-- Catalog: events, sectors and lots (see docs/MODELAGEM.md, section 8.4).
-- IDs are generated by the application (UUID), so there is no DEFAULT here.
-- Money in cents (BIGINT), timestamps in UTC (TIMESTAMPTZ).

CREATE TABLE events (
    id           UUID         PRIMARY KEY,
    organizer_id UUID         NOT NULL,
    name         VARCHAR(200) NOT NULL,
    venue        VARCHAR(200) NOT NULL,
    city         VARCHAR(100) NOT NULL,
    starts_at    TIMESTAMPTZ  NOT NULL,
    status       VARCHAR(20)  NOT NULL,
    CONSTRAINT events_status_check CHECK (status IN ('RASCUNHO', 'PUBLICADO', 'ENCERRADO'))
);

CREATE INDEX events_status_starts_at_idx ON events (status, starts_at);

CREATE TABLE sectors (
    id       UUID         PRIMARY KEY,
    event_id UUID         NOT NULL REFERENCES events (id) ON DELETE CASCADE,
    name     VARCHAR(100) NOT NULL,
    CONSTRAINT sectors_event_name_unique UNIQUE (event_id, name)
);

CREATE TABLE lots (
    id          UUID         PRIMARY KEY,
    sector_id   UUID         NOT NULL REFERENCES sectors (id) ON DELETE CASCADE,
    name        VARCHAR(100) NOT NULL,
    price_cents BIGINT       NOT NULL,
    quantity    INT          NOT NULL,
    sort_order  INT          NOT NULL,
    starts_at   TIMESTAMPTZ  NOT NULL,
    ends_at     TIMESTAMPTZ  NOT NULL,
    CONSTRAINT lots_price_check    CHECK (price_cents >= 0),
    CONSTRAINT lots_quantity_check CHECK (quantity > 0),
    CONSTRAINT lots_window_check   CHECK (ends_at > starts_at),
    CONSTRAINT lots_sector_order_unique UNIQUE (sector_id, sort_order)
);
